/**
 * The appliance's own connection string.
 *
 * This is covered because the shape it handles - a unix socket - silently
 * broke the container's migration step: the URL form libpq uses has an
 * authority with no host, `new URL()` refuses it, and the failure only ever
 * showed up inside a container nobody was watching.
 */
import { describe, expect, it } from 'vitest'
// @ts-expect-error -- plain JS helper the migration scripts use before any build
import { pgConnection } from '../../../../scripts/pg-connect.mjs'
import { connectionTarget } from '../db.js'

describe('pgConnection', () => {
  it('turns the appliance socket URL into options the driver accepts', () => {
    const [options, second] = pgConnection('postgres://yeopjari@/yeopjari?host=/run/postgresql')
    expect(second).toBeUndefined()
    expect(options).toMatchObject({
      host: '/run/postgresql',
      database: 'yeopjari',
      username: 'yeopjari',
      ssl: false,
    })
  })

  it('carries a password through the socket form', () => {
    const [options] = pgConnection('postgres://yeopjari_app:s3cr%40t@/yeopjari?host=/run/postgresql')
    expect(options).toMatchObject({
      host: '/run/postgresql',
      username: 'yeopjari_app',
      password: 's3cr@t',
      database: 'yeopjari',
    })
  })

  it('leaves an ordinary URL alone and requires TLS off-host', () => {
    const [url, options] = pgConnection('postgres://u:p@db.example.com:5432/yeopjari')
    expect(url).toBe('postgres://u:p@db.example.com:5432/yeopjari')
    expect(options).toMatchObject({ ssl: 'require' })
  })

  it('does not demand TLS of a local development database', () => {
    const [, options] = pgConnection('postgres://postgres:devpass@127.0.0.1:55432/yeopjari')
    expect(options).toMatchObject({ ssl: false })
  })

  it('passes extra driver options through both shapes', () => {
    const [socketOptions] = pgConnection('postgres://a@/b?host=/run/postgresql', { max: 1 })
    const [, urlOptions] = pgConnection('postgres://a@h/b', { max: 1 })
    expect(socketOptions).toMatchObject({ max: 1 })
    expect(urlOptions).toMatchObject({ max: 1 })
  })
})

/**
 * The runtime and the migration scripts each carry their own copy, because one
 * runs inside the bundle and the other runs as plain JavaScript before
 * anything is built. They have to agree, and the only way they stay agreeing
 * is if something checks.
 */
describe('connectionTarget matches the script helper', () => {
  const cases = [
    'postgres://yeopjari@/yeopjari?host=/run/postgresql',
    'postgres://yeopjari_app:s3cr%40t@/yeopjari?host=/run/postgresql',
    'postgres://u:p@db.example.com:5432/yeopjari',
    'postgres://postgres:devpass@127.0.0.1:55432/yeopjari',
  ]

  for (const url of cases) {
    it(`agrees on ${url.replace(/:[^:@/]*@/, ':***@')}`, () => {
      const { target, ssl } = connectionTarget(url)
      const [first, second] = pgConnection(url) as [unknown, Record<string, unknown> | undefined]

      if (typeof target === 'string') {
        expect(first).toBe(target)
        expect(second?.ssl).toBe(ssl)
      } else {
        expect(first).toMatchObject({ ...target, ssl })
        expect(second).toBeUndefined()
      }
    })
  }
})

