/**
 * Listing photos.
 *
 * Upload is one photo per request (MEDIA-02). The request reserves the
 * member's storage allowance, sanitises the bytes, and only then marks the
 * asset READY; the bytes are served back through this API, which re-checks the
 * current permission every time and never issues a signed URL (MEDIA-04,
 * MEDIA-06).
 */
import { Router } from '../http/router.js'
import { bytes as byteResponse, json } from '../http/respond.js'
import type { Ctx } from '../http/types.js'
import { AppError, forbidden, notFound, quotaExceeded } from '../errors.js'
import { parseOne, v } from '../util/validate.js'
import { createStorage, newObjectKey, type Storage } from '../media/storage.js'
import { sanitise } from '../media/image.js'

export function mediaRoutes(): Router {
  const router = new Router()

  router.post(
    '/api/v1/media',
    async (ctx) => {
      const accountId = requireAccount(ctx)
      const s = await ctx.settings.pick(
        'media.max_upload_bytes',
        'media.max_long_edge',
        'media.max_megapixels',
        'media.target_bytes',
        'media.thumb_long_edge',
        'media.account_quota_bytes',
        'media.temp_retention_hours',
        'ops.upload_frozen',
      )
      if (s['ops.upload_frozen']) {
        throw new AppError('write_frozen', '사진 업로드가 일시 중단되었습니다.')
      }
      if (ctx.principal.status !== 'approved' || !ctx.principal.verified) {
        throw forbidden('승인된 회원과 유효한 회사 인증이 필요합니다.')
      }

      const uploadRequestId = (ctx.request.headers.get('x-upload-request-id') ?? '').trim()
      if (uploadRequestId && (uploadRequestId.length < 8 || uploadRequestId.length > 100)) {
        throw new AppError('bad_request', 'x-upload-request-id는 8자 이상 100자 이하여야 합니다.')
      }

      // Retrying the same upload returns the first result rather than paying
      // for the work twice (JOB-05).
      if (uploadRequestId) {
        const existing = await ctx.sql<
          { id: string; state: string; width: number; height: number; bytes: number; reject_reason: string }[]
        >`
          SELECT id, state::text AS state, width, height, bytes, reject_reason
          FROM app.media_assets
          WHERE owner_id = ${accountId} AND upload_request_id = ${uploadRequestId}`
        const prior = existing[0]
        if (prior) {
          if (prior.state === 'REJECTED') {
            throw new AppError('bad_request', prior.reject_reason || '사진을 처리할 수 없습니다.')
          }
          return json(assetView(prior), { status: 200 })
        }
      }

      const raw = await ctx.rawBody()

      const used = await ctx.sql<{ total: string }[]>`
        SELECT COALESCE(sum(bytes + thumb_bytes), 0)::text AS total
        FROM app.media_assets
        WHERE owner_id = ${accountId} AND state <> 'DELETED'`
      const usedBytes = Number(used[0]?.total ?? 0)
      if (usedBytes + raw.byteLength > s['media.account_quota_bytes']) {
        throw quotaExceeded(
          `보관 중인 사진이 한도(${Math.floor(s['media.account_quota_bytes'] / 1_048_576)}MB)에 도달했습니다. ` +
            '오래된 매물의 사진을 정리해 주세요.',
          { used_bytes: usedBytes, quota_bytes: s['media.account_quota_bytes'] },
        )
      }

      // A refusal throws, which rolls this transaction back - so there is
      // deliberately no rejected-upload bookkeeping to lose. Re-validating on
      // a retry costs far less than the upload itself.
      const started = Date.now()
      const sanitised = sanitise(raw, {
        maxBytes: s['media.max_upload_bytes'],
        maxLongEdge: s['media.max_long_edge'],
        maxMegapixelsX100: s['media.max_megapixels'],
        targetBytes: s['media.target_bytes'],
        thumbLongEdge: s['media.thumb_long_edge'],
      })

      const storage = createStorage(ctx.env)
      const fullKey = newObjectKey('full')
      const thumbKey = newObjectKey('thumb')
      await storage.put(fullKey, sanitised.full, 'image/jpeg')
      await storage.put(thumbKey, sanitised.thumb, 'image/jpeg')

      const purgeAfter = new Date(Date.now() + s['media.temp_retention_hours'] * 3_600_000)
      const rows = await ctx.sql<
        { id: string; state: string; width: number; height: number; bytes: number; reject_reason: string }[]
      >`
        INSERT INTO app.media_assets
          (owner_id, object_key, thumb_key, bytes, thumb_bytes, width, height,
           state, upload_request_id, ready_at, purge_after)
        VALUES (${accountId}, ${fullKey}, ${thumbKey}, ${sanitised.full.byteLength},
                ${sanitised.thumb.byteLength}, ${sanitised.width}, ${sanitised.height},
                'READY', ${uploadRequestId}, now(), ${purgeAfter})
        RETURNING id, state::text AS state, width, height, bytes, reject_reason`
      const asset = rows[0]
      if (!asset) {
        // The insert lost a race with a concurrent identical upload; clean up
        // the objects we just wrote so they do not leak.
        await storage.delete(fullKey)
        await storage.delete(thumbKey)
        throw new AppError('conflict', '같은 업로드가 이미 처리되었습니다.')
      }

      await ctx.audit({
        action: 'media.uploaded',
        targetType: 'media',
        targetId: asset.id,
        after: {
          bytes: sanitised.full.byteLength,
          width: sanitised.width,
          height: sanitised.height,
          quality: sanitised.quality,
          ms: Date.now() - started,
        },
      })

      return json(assetView(asset), { status: 201 })
    },
    { auth: 'session', heavy: true, freezable: true, summary: '사진 업로드' },
  )

  router.delete(
    '/api/v1/media/:id',
    async (ctx) => {
      const accountId = requireAccount(ctx)
      const id = parseOne(v.uuid({ label: '사진' }), ctx.params.id, 'id')
      const rows = await ctx.sql<{ object_key: string; thumb_key: string; state: string }[]>`
        SELECT object_key, thumb_key, state::text AS state FROM app.media_assets
        WHERE id = ${id} AND owner_id = ${accountId}`
      const asset = rows[0]
      if (!asset) throw notFound('사진을 찾을 수 없습니다.')
      if (asset.state === 'ATTACHED') {
        throw forbidden('매물에 연결된 사진입니다. 매물에서 사진을 제거한 뒤 삭제해 주세요.')
      }

      await ctx.sql`
